/*
 * A207730  Number of 3 X n 0..1 arrays avoiding 0 0 0 and 0 1 0 horizontally
 *          and 0 1 1 and 1 0 1 vertically.
 * https://oeis.org/A207730
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 4, u16 n <= 9, u32 n <= 19, u64 n <= 39, u128 n <= 79,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Recurrence: a(1) = 6, a(2) = 36, for n ≥ 3 the sequence is generated by a
   state‑transition DP on the last two columns.  Horizontal triples 000
   and 010 are forbidden, vertical triples 011 and 101 are forbidden. */
#include <stdint.h>

seq_t a(idx_t n)
{
    if (n == 0) return 0;
    if (n == 1) return 6;

    /* The only allowed 3‑bit columns (vertical constraint). */
    static const uint8_t valid_col[8] = {
        1, 1, 1, 0, 1, 0, 1, 1
    };

    seq_t dp[64];
    seq_t newdp[64];
    for (idx_t i = 0; i < 64; ++i) dp[i] = 0;

    /* Initial state after the first two columns. */
    for (int c1 = 0; c1 < 8; ++c1) {
        if (!valid_col[c1]) continue;
        for (int c2 = 0; c2 < 8; ++c2) {
            if (!valid_col[c2]) continue;
            uint32_t s = 0;
            for (int r = 0; r < 3; ++r) {
                int bit1 = (c1 >> (2 - r)) & 1;   /* row r in column 1 */
                int bit2 = (c2 >> (2 - r)) & 1;   /* row r in column 2 */
                int pair = (bit1 << 1) | bit2;    /* (prevprev,prev) */
                s |= (uint32_t)pair << (4 - 2 * r);
            }
            dp[s] += 1;
        }
    }

    /* DP for columns 3 … n. */
    for (idx_t col = 3; col <= n; ++col) {
        for (idx_t i = 0; i < 64; ++i) newdp[i] = 0;

        for (idx_t s = 0; s < 64; ++s) {
            if (dp[s] == 0) continue;
            for (int b = 0; b < 8; ++b) {
                if (!valid_col[b]) continue;

                uint32_t newS = 0;
                int ok = 1;
                for (int r = 0; r < 3; ++r) {
                    int shift = 4 - 2 * r;
                    int pair  = (s >> shift) & 3;          /* (prevprev,prev) */
                    int vp_prevprev = (pair >> 1) & 1;
                    int vp_prev     =  pair       & 1;
                    int newbit = (b >> (2 - r)) & 1;       /* row r in new col */

                    /* Horizontal restriction 000 and 010. */
                    if ((vp_prevprev == 0 && vp_prev == 0 && newbit == 0) ||
                        (vp_prevprev == 0 && vp_prev == 1 && newbit == 0)) {
                        ok = 0;
                        break;
                    }

                    int new_pair = (vp_prev << 1) | newbit;
                    newS |= (uint32_t)new_pair << shift;
                }
                if (!ok) continue;

                newdp[newS] += dp[s];
            }
        }

        /* Copy newdp into dp for next iteration. */
        for (idx_t i = 0; i < 64; ++i) dp[i] = newdp[i];
    }

    /* Sum over all states to get the final count. */
    seq_t result = 0;
    for (idx_t i = 0; i < 64; ++i) result += dp[i];
    return result;
}
